    api.overlay().querySelectorAll('[data-route-role-upload]').forEach(form=>form.addEventListener('submit',async event=>{event.preventDefault();const role=form.dataset.routeRoleUpload,file=form.querySelector('[name="image"]').files?.[0];if(!file){api.notify('Bitte ein Bild auswählen.');return}const labels={collector:'Sammler',processor:'Verarbeiter',seller:'Verkäufer',flyer:'Flyer'};try{route.images=await api.uploadRouteImages(route.id,[file],role,`${labels[role]}${role==='flyer'?'':' · '+route.name}`);routeDetail(route,'images');api.notify(`${labels[role]}-Bild hochgeladen.`)}catch(error){api.notify(`Bildupload fehlgeschlagen: ${error.message}`)}}));
